.garden-workspace .garden-disclosure-toggle,.garden-workspace .garden-create-summary{list-style:none;cursor:pointer;min-height:44px;padding:10px 14px;border:1px solid var(--garden-border);border-radius:8px;background:#f8faf8;color:#24563e;font-size:13px;font-weight:650;line-height:1.5;display:flex;align-items:center;gap:12px;transition:background .15s,border-color .15s}
